package render

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"html"
	"path"
	"strconv"
	"strings"
	"sync"
)

// usmap.json is generated by tools/usmap/build.sh from Census Bureau
// cartographic boundaries (public domain).
//
//go:embed usmap.json
var usmapJSON []byte

type usmapBox struct {
	X, Y, W, H float64
	Frame      bool `json:"frame"`
}

type usmapRegion struct {
	Code    string    `json:"code"`
	Name    string    `json:"name"`
	Aliases []string  `json:"aliases"`
	D       string    `json:"d"`
	Box     *usmapBox `json:"box"`
}

var usmapData = sync.OnceValue(func() (m struct {
	W, H    float64
	Regions []usmapRegion `json:"regions"`
}) {
	if err := json.Unmarshal(usmapJSON, &m); err != nil {
		panic("usmap.json: " + err.Error())
	}
	return m
})

// usmapBlock renders a ```usmap block: a map of U.S. states and territories
// where each one with a published folder or note (by name, alias or postal
// code) inside the named folder links to it.
func (r *Renderer) usmapBlock(code string, line int, ctx Context) (string, error) {
	arg := strings.TrimSpace(code)
	folder, ok := r.usmapFolder(arg, ctx)
	if !ok {
		r.Warn(ctx.Path, line, fmt.Sprintf("usmap: no published folder %q", arg))
	}
	targets := map[string]string{} // lower-cased name -> URL
	if ok {
		for f, slug := range r.Pub.Folders {
			if path.Dir(f) == folder && f != folder {
				targets[strings.ToLower(path.Base(f))] = r.URLs.PageURL(slug)
			}
		}
		for p, slug := range r.Pub.Pages {
			if path.Dir(p) == folder && slug != "" && r.Pub.FolderNote(folder) != p {
				name := strings.ToLower(strings.TrimSuffix(path.Base(p), path.Ext(p)))
				if _, isFolder := targets[name]; !isFolder {
					targets[name] = r.URLs.PageURL(slug)
				}
			}
		}
	}

	m := usmapData()
	var b strings.Builder
	b.WriteString(`<figure class="usmap"><svg viewBox="0 0 ` + num(m.W) + " " + num(m.H) +
		`" role="group" aria-label="Map of U.S. states and territories">` + "\n")
	for _, reg := range m.Regions {
		url := ""
		for _, n := range append([]string{reg.Name, reg.Code}, reg.Aliases...) {
			if u, ok := targets[strings.ToLower(n)]; ok {
				url = u
				break
			}
		}
		name := html.EscapeString(reg.Name)
		if url != "" {
			b.WriteString(`<a href="` + html.EscapeString(url) + `"><title>` + name + `</title>`)
		} else {
			b.WriteString(`<g class="off"><title>` + name + `</title>`)
		}
		b.WriteString(`<path d="` + reg.D + `"/>`)
		if bx := reg.Box; bx != nil {
			cls, ty := "sq", bx.Y+bx.H/2
			if bx.Frame {
				cls, ty = "inset", bx.Y+bx.H-7
			}
			b.WriteString(`<rect class="` + cls + `" x="` + num(bx.X) + `" y="` + num(bx.Y) + `" width="` + num(bx.W) + `" height="` + num(bx.H) +
				`" rx="3"/><text x="` + num(bx.X+bx.W/2) + `" y="` + num(ty) + `">` + reg.Code + `</text>`)
		}
		if url != "" {
			b.WriteString("</a>\n")
		} else {
			b.WriteString("</g>\n")
		}
	}
	b.WriteString("</svg></figure>\n")
	return "\n" + b.String(), nil
}

// usmapFolder finds the published folder an argument names: relative to the
// note's folder, then to the published root, then to the vault. Empty means
// the note's own folder.
func (r *Renderer) usmapFolder(arg string, ctx Context) (string, bool) {
	for _, f := range []string{path.Join(path.Dir(ctx.Path), arg), path.Join(r.Pub.Root, arg), path.Clean(arg)} {
		if _, ok := r.Pub.Folders[f]; ok {
			return f, true
		}
	}
	return "", false
}

func num(f float64) string { return strconv.FormatFloat(f, 'f', -1, 64) }
